using System.Security.Claims; using HabitFlow.Application; using Microsoft.AspNetCore.Authentication; using Microsoft.AspNetCore.Authentication.Cookies; using Microsoft.AspNetCore.Mvc; namespace HabitFlow.Web.Controllers; public class AuthController(AuthService auth):Controller{[HttpGet("/login")]public IActionResult Login()=>View();[ValidateAntiForgeryToken,HttpPost("/login")]public async Task<IActionResult> Login(LoginDto dto){var r=await auth.LoginAsync(dto,HttpContext.Connection.RemoteIpAddress?.ToString(),Request.Headers.UserAgent); if(r.IsFailure){TempData["Error"]=r.Error.Message;return View(dto);} var u=r.Value!; await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.Name),new Claim(ClaimTypes.Email,u.Email),new Claim(ClaimTypes.Role,u.Role.ToString())],CookieAuthenticationDefaults.AuthenticationScheme)));return RedirectToAction("Index","Dashboard");}[HttpGet("/register")]public IActionResult Register()=>View();[ValidateAntiForgeryToken,HttpPost("/register")]public async Task<IActionResult> Register(RegisterDto dto){var r=await auth.RegisterAsync(dto); if(r.IsFailure){TempData["Error"]=r.Error.Message;return View(dto);} return RedirectToAction("Login");}[ValidateAntiForgeryToken,HttpPost("/logout")]public async Task<IActionResult> Logout(){await HttpContext.SignOutAsync();return RedirectToAction("Index","Home");}}
